<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
$user=app_require_permission('wholesale.view');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Demand</title><style>:root{--bg:#f3f2ee;--panel:#fff;--ink:#171815;--muted:#69706a;--line:#dddcd6;--accent:#d94a2b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select{font:inherit}.top{height:64px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 22px}.btn{display:inline-flex;align-items:center;padding:9px 12px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);text-decoration:none;font-size:10px;font-weight:850;cursor:pointer}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.shell{max-width:1350px;margin:auto;padding:26px}.hero{display:flex;justify-content:space-between;gap:16px;align-items:end;margin-bottom:18px}.hero h1{font-size:38px;letter-spacing:-.05em;margin:5px 0}.hero p{font-size:11px;color:var(--muted);max-width:750px}.eyebrow{font-size:9px;text-transform:uppercase;font-weight:950;color:var(--accent)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}.stat,.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:15px}.stat small{font-size:8px;text-transform:uppercase;font-weight:900;color:var(--muted)}.stat strong{display:block;font-size:25px;margin-top:4px}.cols{display:grid;grid-template-columns:1.35fr .85fr;gap:12px}.panel h2{margin:0 0 4px;font-size:15px}.panel>p{font-size:9px;color:var(--muted);margin:0 0 12px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:9px 7px;border-bottom:1px solid var(--line);font-size:9px;text-align:left}.table th{font-size:8px;text-transform:uppercase;color:var(--muted)}.neg{font-weight:900;color:#9f2f22}.field{width:100%;min-height:38px;border:1px solid var(--line);border-radius:8px;padding:7px}.profile{border:1px solid var(--line);border-radius:10px;padding:10px;margin:8px 0}.profile strong{font-size:10px}.profile small{display:block;color:var(--muted);font-size:8px;margin:2px 0 7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.status{position:fixed;right:18px;bottom:18px;background:#171b1a;color:#fff;padding:10px 13px;border-radius:9px;font-size:10px;display:none}@media(max-width:850px){.stats,.cols,.grid{grid-template-columns:1fr 1fr}.cols{grid-template-columns:1fr}}@media(max-width:560px){.stats,.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>Wholesale Demand</strong><div><a class="btn" href="wholesale-order-entry.php">Quote / Order</a> <a class="btn" href="purchasing.php">Purchasing</a> <a class="btn" href="wholesale-accounts.php">Accounts</a></div></header><main class="shell"><div class="hero"><div><span class="eyebrow">W2 demand commitments</span><h1>Committed demand → purchasing</h1><p>Confirmed wholesale orders reserve recipe ingredients for planning without reducing physical on-hand inventory. Purchasing sees the resulting available-to-promise pressure.</p></div><?php if(app_has_permission('wholesale.manage',$user)):?><button class="btn primary" id="sync">Rebuild commitments</button><?php endif;?></div><div class="stats"><div class="stat"><small>Wholesale orders reserved</small><strong id="orders">—</strong></div><div class="stat"><small>Ingredient items</small><strong id="items">—</strong></div><div class="stat"><small>Planning horizon</small><strong id="horizon">7 days</strong></div><div class="stat"><small>Shortage items</small><strong id="shortages">—</strong></div></div><div class="cols"><section class="panel"><h2>7-day ingredient commitments</h2><p>Available to promise = physical on-hand − active wholesale commitments. Units are normalized to each inventory item's base unit.</p><table class="table"><thead><tr><th>Ingredient</th><th>On hand</th><th>Committed</th><th>ATP</th><th>Replenish</th><th>Orders</th><th>Next</th></tr></thead><tbody id="forecast"></tbody></table></section><section class="panel"><h2>SKU production mapping</h2><p>Recipe yield per batch is preferred. 5L content quantity/unit provides a fallback when the recipe records finished output.</p><div id="profiles"></div></section></div></main><div id="status" class="status"></div><script>window.WD={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,canManage:<?=app_has_permission('wholesale.manage',$user)?'true':'false'?>};</script><script>(()=>{const c=window.WD,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch])),fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:3}),toast=t=>{const el=$('status');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',2200)};async function req(url,opt={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(opt.body?{'Content-Type':'application/json','X-CSRF-Token':c.csrf}:{}),...(opt.headers||{})},...opt}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function post(b){return req('api/wholesale-demand.php',{method:'POST',body:JSON.stringify({...b,csrf_token:c.csrf})})}async function load(){const d=await req('api/wholesale-demand.php?action=forecast&days=7'),f=d.forecast,t=f.totals;$('orders').textContent=t.orders;$('items').textContent=t.items;$('horizon').textContent=`${f.days} days`;$('shortages').textContent=t.shortages;$('forecast').innerHTML=(f.items||[]).map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small>${esc(x.unit)}</small></td><td>${fmt(x.onHand)}</td><td>${fmt(x.committed)}</td><td class="${x.availableToPromise<0?'neg':''}">${fmt(x.availableToPromise)}</td><td>${fmt(x.replenishToTarget)}</td><td>${x.orderCount}</td><td>${esc(x.nextDate||'—')}</td></tr>`).join('')||'<tr><td colspan="7">No committed wholesale ingredient demand in this window.</td></tr>';$('profiles').innerHTML=(d.profiles||[]).map(p=>`<div class="profile" data-id="${esc(p.public_id)}"><strong>${esc(p.sku)} · ${esc(p.name)}</strong><small>${esc(p.product_name)} · recipe: ${esc(p.recipe_name||'not mapped')}</small><div class="grid"><input class="field y" type="number" step=".0001" placeholder="Sell units / batch" value="${esc(p.recipe_yield_per_batch??'')}"><input class="field yu" placeholder="Yield unit" value="${esc(p.recipe_yield_unit||'')}"><input class="field cq" type="number" step=".0001" placeholder="Content qty e.g. 5" value="${esc(p.content_quantity??'')}"><input class="field cu" placeholder="Content unit e.g. L" value="${esc(p.content_uom||'')}">${c.canManage?'<button class="btn save">Save mapping</button>':''}</div></div>`).join('')||'No wholesale SKUs configured.';document.querySelectorAll('.save').forEach(b=>b.onclick=async()=>{const p=b.closest('.profile');try{const d=await post({action:'sku_production',skuId:p.dataset.id,recipeYieldPerBatch:p.querySelector('.y').value,recipeYieldUnit:p.querySelector('.yu').value,contentQuantity:p.querySelector('.cq').value,contentUom:p.querySelector('.cu').value});toast(`Production mapping saved · ${d.sync?.issues?.length||0} mapping issues`);await load()}catch(e){alert(e.message)}})}const syncBtn=$('sync');if(syncBtn)syncBtn.onclick=async()=>{try{const d=await post({action:'sync'}),issues=d.result.issues?.length||0;toast(`Synced ${d.result.orders||0} wholesale orders · ${issues} mapping issues`);await load()}catch(e){alert(e.message)}};load().catch(e=>alert(e.message))})();</script></body></html>